guards.remove:
if (executionActors.has(event.actor.id)) {
  readiness.reasons.push("an execution actor cannot accept its own work");
  readiness.ready = false;
}

if (contractNeedsVerification && !qualifyingVerification) {
  reasons.push(board.integration === null
    ? "required passing verification for the current contract revision is missing"
    : "required passing verification bound to the exact Work integration head is missing");
}

if ((value.type === "SCOUT" || value.type === "REVIEW") && value.writeScope.length > 0) {
  ctx.addIssue({
    code: "custom",
    path: ["writeScope"],
    message: `${value.type} work cannot carry production write scope`,
  });
}

if (hasRequiredProof && !value.verificationPolicy.required) {
  ctx.addIssue({
    code: "custom",
    path: ["verificationPolicy", "required"],
    message: "verification must be required when acceptance criteria or evidence requirements are required",
  });
}

if (result.status === "pass" && result.evidence.length === 0) {
  result = VerificationCheckResultSchema.parse({ ...result, status: "error", summary: "passing verifier check returned no evidence" });
}

if (before.digest !== after.digest) {
  violations.push("read-only Crew mission changed its workspace");
}

if (!pathAllowed(path, work.writeScope)) {
  violations.push(`changed path ${path} is outside Work writeScope`);
}

if (recordDigest(unsigned) !== storedDigest) {
  throw new LedgerIntegrityError(`record ${expectedGlobal} digest does not match its contents`, expectedGlobal);
}

if (!falsifiable) {
  throw new Error(
    `required acceptance criterion ${criterion.id} is proven by a check with no negative control, so nothing establishes that check can detect a failure; `
    + "add a negative control, or record a falsifiability exemption on the Work contract naming a human",
  );
}

...(resolution.selection.authorization === undefined
  ? {}
  : { authorization: resolution.selection.authorization }),

if (contains(candidate, derivative)) {
  throw new DerivativeContainmentError(`derivative root ${derivative} is inside candidate ${candidate}; every mutation would land in the candidate`);
}

if (resolved !== this.root && !resolved.startsWith(this.root + sep)) {
  throw new DerivativeEscapeError(
    `path ${relativePath} resolves to ${resolved}, outside derivative ${this.root}; a proof may only write inside its derivative`,
  );
}

if (differences.length > 0) {
  invalidations.push({
    code: "candidate-drifted",
    detail:
      `the authoritative candidate changed during the proof (${differences.join(", ")}); `
      + "this proof's conclusion is about an artifact that no longer exists",
  });
}

if (identity.digest !== expectedDigest) {
  // Either the candidate moved while we copied it, or the copy is not
  // faithful. Both make every later conclusion about the wrong artifact.
  throw new Error(
    `derivative digest ${identity.digest} does not match the pinned candidate ${expectedDigest}; `
    + "the candidate changed during creation or the copy is not faithful",
  );
}

if (resolved !== realRoot && !contains(realRoot, resolved)) {
  throw new DerivativeLinkEscapeError(
    `symlink ${relPath} -> ${target} resolves to ${resolved}, outside the derivative root; a proof would hold a path out of the derivative`,
    relPath,
    target,
    resolved,
  );
}

if (isAbsolute(target)) {
  throw new DerivativeLinkEscapeError(
    `symlink ${relPath} -> ${target} has an absolute target; its resolution depends on filesystem state outside the derivative, which no digest covers`,
    relPath,
    target,
  );
}

if (requirements.requireSandboxCapableHost && !(await hostImposesContainment(entry))) {
  // No authorization overrides this one. Prompt text and human trust are
  // not an OS write boundary (issue #11); whoever vouches for the
  // provider, the filesystem is still the filesystem.
  rejections.push({
    providerId: entry.provider.id,
    reason: "work with write access requires a host that imposes OS containment (HostCapabilities.sandbox)",
  });
  continue;
}

if (!allowedWriteAccess.has(descriptor.writeAccess) && authorization === undefined) {
  rejections.push({
    providerId: entry.provider.id,
    reason: `write access ${descriptor.writeAccess} is not allowed by this supervision policy`,
  });
  continue;
}

if (absolute !== executionRoot && !absolute.startsWith(`${executionRoot}/`)) {
  refuseScope(uri, executionRoot, "absolute path is outside the execution root");
}

case "authority.granted":
case "authority.denied": {
  board = {
    ...board,
    authorityDecisions: [
      ...board.authorityDecisions,
      {
        eventId: event.id,
        decision: event.type === "authority.granted" ? "granted" : "denied",
        reason: event.payload.reason ?? "",
      },
    ],
  };
  break;
}

if (observation.authority !== undefined) {
  await append(
    observation.authority.decision === "granted" ? "authority.granted" : "authority.denied",
    {
      policy: work.authority,
      reason: `${observation.authority.reason} [boundary: ${observation.authority.boundary}]`,
    },
    { taskId, attemptId, actor: workerActor },
  );
}

...(options.guardedToolMediation === undefined ? {} : {
  canUseTool: async (call: GuardToolCall): Promise<GuardVerdict> => {
    let evaluation: GuardEvaluation;
    try {
      evaluation = await options.guardedToolMediation!.evaluate(call);
    } catch (cause) {
      const refusal = routeRefusal(
        call,
        this.#route,
        `DSH route ${this.#route.workerId} could not complete guarded mediation for this native tool call, so the effect is refused. ${cause instanceof Error ? `${cause.name}: ${cause.message}` : String(cause)}`,
        this.#now,
      );
      observeBestEffort(observations, () => ({
        kind: "diagnostic",
        occurredAt: this.#now(),
        detail: `Guard mediation failed for a native tool call; refused: ${refusal.rationale}`.slice(0, 4000),
      }));
      return refusal;
    }

    // This hook is answered by a machine in a non-interactive permission
    // mode, so nothing but an explicit allow may authorize the effect.
    const effected = permittingVerdict(evaluation.verdict, this.#route);
    observeBestEffort(observations, () => ({
      kind: "diagnostic",
      occurredAt: this.#now(),
      detail: effected.decision === evaluation.verdict.decision
        ? `Guard evaluated native tool ${evaluation.request.tool.name}: ${evaluation.verdict.decision}`
        : `Guard evaluated native tool ${evaluation.request.tool.name}: ${evaluation.verdict.decision}, effected as ${effected.decision} (${this.#route.permissionMode} has no approval channel)`,
      guardEvaluation: summarizeGuardEvaluation(evaluation),
    }));
    return effected;
  },
}),

case "guard.evaluated": {
  board = {
    ...board,
    guardEvaluations: [
      ...board.guardEvaluations,
      { eventId: event.id, ...event.payload },
    ],
  };
  break;
}

if (decision !== "allow" && decision !== "forbid" && (this.#options.approvalChannel ?? "none") !== "interactive") {
  return {
    ...verdict,
    decision: "forbid",
    rationale: `Guard decided "${decision}" but this seam has no human approval channel, so the effect is refused. ${verdict.rationale}`.slice(0, 4000),
    ruleHits: [...verdict.ruleHits, `mediation-no-approval-channel:${decision}`],
  };
}

if (verdict.decision !== "allow" && verdict.decision !== "forbid") {
  return {
    ...verdict,
    decision: "forbid",
    rationale: `Guard decided "${verdict.decision}", which requires a human; DSH route ${route.workerId} runs permissionMode ${route.permissionMode} and cannot ask one, so the effect is refused. ${verdict.rationale}`.slice(0, 4000),
    ruleHits: [...verdict.ruleHits, `dsh-route-no-approval-channel:${verdict.decision}`],
  };
}

const nativeCapabilities = DshSubagentRuntimeCapabilitiesSchema.parse(await runtime.capabilities());
if (!nativeCapabilities.guardedToolMediation) {
  throw new Error(`DSH product route ${this.#route.workerId} cannot mediate native tool calls synchronously`);
}

const acceptable = evidence.some((item) => evidenceSatisfiesRequirement(requirement, item));
if (!acceptable) {
  reasons.push(`required evidence ${requirement.id} is not satisfied by an accepted evidence kind`);
}

...primary.filter((check) => check.requirementIds.includes(requirement.id)).flatMap((check) => {
          const result = byCheck.get(check.id);
          return result?.status === "pass" ? result.evidence : [];
        }),

if (event.payload.checkpoint.remoteStatus !== "pushed" || event.payload.checkpoint.remoteRef === undefined) {
  return violation(board, event, "integration-candidate-not-remote", "integration candidate must be durably pushed before it enters shared Work truth");
}

if (result.proofHead !== result.head || proof?.status !== "pass" || proof.contractRevision !== this.#requireBoard().contractRevision) {
  await this.#append("integration.failed", {
    lockId,
    checkpointId,
    reason: "integrated artifact lacks passing proof bound to its exact head",
    semanticConflict: false,
    preservedRefs: [projected.checkpoint.remoteRef].filter((value): value is string => value !== undefined),
  });
  throw new IntegrationControllerError("integrated artifact lacks passing proof bound to its exact head");
}

const harnessOwnedGitOperation = matchHarnessOwnedGitOperation(request);
if (harnessOwnedGitOperation !== null) {
  ruleHits.push("integration-git-authority:harness-owned");
  return verdict(
    "forbid",
    `${harnessOwnedGitOperation} is owned by the Work Integration Controller, not by a worker Attempt.`,
    "critical",
    ruleHits,
  );
}

if (this.#actor.kind !== "human" && this.#actor.kind !== "service") {
  throw new IntegrationControllerError(`actor ${this.#actor.id} lacks integration operator authority`);
}

await append(
  "attempt.failed",
  { reason: `attempt deadline ${attemptDeadlineAt} exceeded at ${raceOutcome.observedAt}`, recoverable: false },
  { taskId, attemptId, actor: workerActor },
  raceOutcome.observedAt,
);

if (decision.kind === "tripped") {
  throw new IntegrationHorizonExceededError(policyId, decision.reasons.map((reason) => reason.signal));
}

} else if (trialsByCase.some((entry) => entry.accepted < entry.required)) {
  verdict = "insufficient-evidence";
  const short = trialsByCase.filter((entry) => entry.accepted < entry.required);
  reasons.push(`${short.length} case(s) have fewer than ${spec.trialsPerArm} paired trials`);
